const { fonte } = $json;
const FUSO = 'America/Sao_Paulo';
const diaLocal = (instante) => new Intl.DateTimeFormat('en-CA', { timeZone: FUSO, year: 'numeric', month: '2-digit', day: '2-digit' }).format(instante);
const DIA_EM_MS = 86400000;
const agora = Date.now();
const JANELA_DE_TAREFAS_EM_DIAS = 30;
return [{
  json: {
    inicio: agora,
    versaoApi: 'crm-v1',
    fonte,
    tarefasDe: `${diaLocal(new Date(agora - JANELA_DE_TAREFAS_EM_DIAS * DIA_EM_MS))}T00:00:00`,
    tarefasAte: `${diaLocal(new Date(agora + JANELA_DE_TAREFAS_EM_DIAS * DIA_EM_MS))}T23:59:59`,
  },
}];

const resposta = $input.first().json;
const ok = !resposta.error && resposta.statusCode >= 200 && resposta.statusCode < 300 && Array.isArray(resposta.body);
const funis = ok ? resposta.body.filter((funil) => funil && (funil.id ?? funil._id) != null) : [];
if (funis.length === 0) return [{ json: { temFunil: false } }];
return funis.map((funil) => ({ json: { temFunil: true, funilId: String(funil.id ?? funil._id) } }));

const LIMITE_DE_PAGINAS = 60;
const TETO_DA_API = 10000;
const contexto = $('Montar requisição').first().json;
const respostaDosFunis = $('Listar funis').first().json;
const paginas = $input.all().map((item) => item.json).filter((json) => json && (json.statusCode !== undefined || json.error));
const respostas = [respostaDosFunis, ...paginas];
function respostasDe(nome) {
  try {
    return $(nome).all().map((item) => item.json).filter((json) => json && (json.statusCode !== undefined || json.error));
  } catch {
    return [];
  }
}
const NOS_DE_CATALOGO = ['Listar fontes', 'Listar campanhas', 'Listar produtos', 'Listar usuários', 'Listar tarefas'];
const porCatalogo = Object.fromEntries(NOS_DE_CATALOGO.map((nome) => [nome, respostasDe(nome)]));
const chamadasDeCatalogo = Object.values(porCatalogo).flat();
const requests = respostas.length + chamadasDeCatalogo.length;
const bytes = respostas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const falhaDeRede = respostas.find((resposta) => resposta.error);
if (falhaDeRede) {
  const detalhe = falhaDeRede.error?.message ?? String(falhaDeRede.error);
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.slice(0, 500) }]);
}

const recusada = respostas.find((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300));
if (recusada) {
  const corpo = recusada.body ?? {};
  const detalhe = String(corpo.errors?.error_message || corpo.error || corpo.message || `HTTP ${recusada.statusCode}`).slice(0, 500);
  const limiteDeUso = recusada.statusCode === 429 || /RATE_LIMIT_EXC/i.test(JSON.stringify(corpo));
  if (limiteDeUso) return devolver([], [{ causa: 'limite_de_uso', detalhe }]);
  const semAcesso = recusada.statusCode === 401 || recusada.statusCode === 403;
  return devolver([], [{ causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe }]);
}

const ROTULO_MAXIMO = 200;
const texto = (valor) => {
  if (typeof valor !== 'string' && typeof valor !== 'number') return null;
  const limpo = String(valor).trim();
  return limpo ? limpo.slice(0, ROTULO_MAXIMO) : null;
};
const identificador = (valor) => {
  const id = texto(valor);
  return id && /^[A-Za-z0-9_-]+$/.test(id) ? id : null;
};
const numero = (valor) => {
  if (valor === null || valor === undefined || valor === '') return null;
  const convertido = Number(valor);
  return Number.isFinite(convertido) ? convertido : null;
};
const booleano = (valor) => (typeof valor === 'boolean' ? valor : null);
const instante = (valor) => (typeof valor === 'string' && valor ? valor : null);
const enumeracao = (valor) => (typeof valor === 'string' && /^[A-Za-z0-9_]{1,40}$/.test(valor) ? valor : null);
const registrosDe = (nome, chave) => porCatalogo[nome]
  .filter((resposta) => resposta.statusCode >= 200 && resposta.statusCode < 300)
  .flatMap((resposta) => (Array.isArray(resposta.body) ? resposta.body : Array.isArray(resposta.body?.[chave]) ? resposta.body[chave] : []));
const idDe = (objeto) => identificador(objeto?.id ?? objeto?._id);

const etapas = new Map();
for (const funil of Array.isArray(respostaDosFunis.body) ? respostaDosFunis.body : []) {
  const pipelineId = identificador(funil?.id ?? funil?._id);
  for (const etapa of Array.isArray(funil?.deal_stages) ? funil.deal_stages : []) {
    const etapaId = identificador(etapa?.id ?? etapa?._id);
    if (!etapaId) continue;
    etapas.set(etapaId, { pipelineId, pipelineName: texto(funil.name), stageOrder: numero(etapa.order) });
  }
}

function linhaDa(negociacao) {
  const dealId = identificador(negociacao?.id ?? negociacao?._id);
  if (!dealId) return null;
  const etapa = negociacao.deal_stage ?? {};
  const stageId = identificador(etapa.id ?? etapa._id);
  const doFunil = (stageId && etapas.get(stageId)) || {};
  return {
    dealId,
    pipelineId: doFunil.pipelineId ?? null,
    pipelineName: doFunil.pipelineName ?? null,
    stageId,
    stageName: texto(etapa.name),
    stageOrder: doFunil.stageOrder ?? null,
    win: booleano(negociacao.win),
    hold: booleano(negociacao.hold),
    amountTotal: numero(negociacao.amount_total),
    amountMonthly: numero(negociacao.amount_montly ?? negociacao.amount_monthly),
    amountUnique: numero(negociacao.amount_unique),
    createdAt: instante(negociacao.created_at),
    updatedAt: instante(negociacao.updated_at),
    closedAt: instante(negociacao.closed_at),
    dealSourceName: texto(negociacao.deal_source?.name),
    campaignName: texto(negociacao.campaign?.name),
    userId: idDe(negociacao.user),
    dealSourceId: idDe(negociacao.deal_source),
    campaignId: idDe(negociacao.campaign),
  };
}

const porId = new Map();
const porFunil = new Map();
for (const pagina of paginas) {
  const negociacoes = Array.isArray(pagina.body?.deals) ? pagina.body.deals : [];
  const linhasDaPagina = negociacoes.map(linhaDa).filter(Boolean);
  for (const linha of linhasDaPagina) porId.set(linha.dealId, linha);
  const funil = linhasDaPagina[0]?.pipelineId ?? 'sem_funil';
  const resumo = porFunil.get(funil) ?? { paginas: 0, coletadas: 0, total: 0, temMais: false };
  resumo.paginas += 1;
  resumo.coletadas += linhasDaPagina.length;
  resumo.total = Math.max(resumo.total, Number(pagina.body?.total ?? 0));
  resumo.temMais = resumo.temMais || pagina.body?.has_more === true;
  porFunil.set(funil, resumo);
}

const negociacoes = [];
for (const pagina of paginas) {
  if (Array.isArray(pagina.body?.deals)) negociacoes.push(...pagina.body.deals);
}

const catalogo = [];
const marcar = (tabela, linha) => catalogo.push({ _tabela: tabela, ...linha });

for (const funil of Array.isArray(respostaDosFunis.body) ? respostaDosFunis.body : []) {
  const funilId = identificador(funil?.id ?? funil?._id);
  if (!funilId) continue;
  marcar('dim_funil', { funilId, nome: texto(funil.name) });
  for (const etapa of Array.isArray(funil.deal_stages) ? funil.deal_stages : []) {
    const etapaId = idDe(etapa);
    if (etapaId) marcar('dim_etapa', { etapaId, funilId, nome: texto(etapa.name), ordem: numero(etapa.order) });
  }
}
for (const fonte of registrosDe('Listar fontes', 'deal_sources')) {
  const fonteId = idDe(fonte);
  if (fonteId) marcar('dim_fonte', { fonteId, nome: texto(fonte.name) });
}
for (const campanha of registrosDe('Listar campanhas', 'campaigns')) {
  const campanhaId = idDe(campanha);
  if (campanhaId) marcar('dim_campanha', { campanhaId, nome: texto(campanha.name) });
}
for (const produto of registrosDe('Listar produtos', 'products')) {
  const produtoId = idDe(produto);
  if (produtoId) marcar('dim_produto', { produtoId, nome: texto(produto.name), preco: numero(produto.base_price ?? produto.price), ativo: booleano(produto.visible ?? produto.active) });
}
for (const usuario of registrosDe('Listar usuários', 'users')) {
  const usuarioId = idDe(usuario);
  if (usuarioId) marcar('dim_usuario', { usuarioId, ativo: booleano(usuario.active) });
}

for (const negociacao of negociacoes) {
  const dealId = idDe(negociacao);
  if (!dealId) continue;
  for (const produto of Array.isArray(negociacao.deal_products) ? negociacao.deal_products : []) {
    const dealProdutoId = idDe(produto);
    if (!dealProdutoId) continue;
    marcar('negociacao_produtos', {
      dealId,
      dealProdutoId,
      produtoId: identificador(produto.product_id ?? produto.product?.id ?? produto.product?._id),
      quantidade: numero(produto.amount),
      preco: numero(produto.price),
      desconto: numero(produto.discount),
      total: numero(produto.total),
    });
  }
  for (const historico of Array.isArray(negociacao.deal_stage_histories) ? negociacao.deal_stage_histories : []) {
    const etapaId = identificador(historico?.deal_stage?.id ?? historico?.deal_stage?._id ?? historico?.deal_stage_id);
    const entrouEm = instante(historico?.created_at ?? historico?.start_date);
    if (etapaId && entrouEm) marcar('negociacao_etapas', { dealId, etapaId, entrouEm });
  }
}

const DIA_ISO = /^\d{4}-\d{2}-\d{2}/;
const tarefasPorDia = new Map();
for (const tarefa of registrosDe('Listar tarefas', 'tasks')) {
  const dataDia = typeof tarefa?.date === 'string' && DIA_ISO.test(tarefa.date) ? tarefa.date.slice(0, 10) : null;
  if (!dataDia) continue;
  const tipo = enumeracao(tarefa.type) ?? 'outro';
  const status = tarefa.done === true ? 'concluida' : 'pendente';
  const chave = [dataDia, tipo, status].join('|');
  const anterior = tarefasPorDia.get(chave);
  tarefasPorDia.set(chave, { dataDia, tipo, status, quantidade: (anterior?.quantidade ?? 0) + 1 });
}
for (const resumo of tarefasPorDia.values()) marcar('tarefas_diarias', resumo);

const tarefasTruncadas = (porCatalogo['Listar tarefas'].at(-1)?.body?.has_more) === true;
const catalogosTruncados = ['Listar fontes', 'Listar campanhas', 'Listar produtos', 'Listar usuários']
  .filter((nome) => porCatalogo[nome]?.at(-1)?.body?.has_more === true);

const linhas = [...porId.values()];
if (linhas.length === 0) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);

const truncados = [...porFunil.entries()].filter(([, resumo]) =>
  (resumo.paginas >= LIMITE_DE_PAGINAS && resumo.temMais) || (resumo.coletadas >= TETO_DA_API && resumo.coletadas < resumo.total));
const motivos = [];
if (truncados.length > 0) {
  motivos.push(`funil acima do teto de paginação: ${truncados.map(([funil, resumo]) => `${funil}: ${resumo.coletadas}/${resumo.total}`).join('; ')}`);
}
if (tarefasTruncadas) motivos.push('tarefas acima do teto de paginação');
if (catalogosTruncados.length > 0) motivos.push(`catálogos acima do teto de paginação: ${catalogosTruncados.join(', ')}`);
const todas = [...linhas, ...catalogo];
if (motivos.length > 0) return devolver(todas, [{ causa: 'coleta_incompleta', detalhe: motivos.join('; ').slice(0, 500) }]);

return devolver(todas, []);
